<?php
$h=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
if(!empty($list_note)): foreach($list_note as $lesson): ?>
<div class="col-lg-4 col-md-6 school-workspace"><article class="workspace-card note-library-card"><p class="workspace-eyebrow"><?php echo $h($lesson['week']); ?> · <?php echo $lesson['type']==='text'?'Lesson note':'Learning resource'; ?></p><h2><?php echo $h($lesson['topic']); ?></h2><p class="workspace-muted">Added <?php echo $h(date('j M Y',strtotime($lesson['rectime']))); ?></p><div class="workspace-actions"><a class="workspace-button" href="../../app/router.php?pageid=note&amp;ref=<?php echo (int)$lesson['noteid']; ?>">Read lesson</a><?php if($_SESSION['user_type']==='Instructor' && ($lesson['staffid'] ?? '')===$_SESSION['active']): ?><a class="workspace-button secondary" href="../../app/router.php?pageid=resources&amp;item=modify_note&amp;item_ref=<?php echo (int)$lesson['noteid']; ?>">Edit</a><?php endif; ?></div></article></div>
<?php endforeach;else: ?><div class="col-12 school-workspace"><section class="workspace-card workspace-empty"><h2>No lesson notes yet</h2><p>Your subject notes will appear here when your teacher adds them.</p></section></div><?php endif; ?>
